package io.github.pennstatecs.geokit.projection

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.security.MessageDigest

/**
 * Zone suggestion from county-defined SPCS83 extents (resource generated by
 * tools/coords/gen_spcs_boundaries.py from the EPSG county lists and Census 1:20M county lines).
 * Test points are kilometres from any zone boundary; the generalised lines are not exact near one.
 */
class SpcsZoneLocatorTest {
    private val locator = SpcsZoneLocator.SPCS83

    private fun assertZone(ngs: Int, lat: Double, lon: Double, basis: SpcsZoneBasis = SpcsZoneBasis.COUNTY_BOUNDARY) {
        val s = locator.locate(lat, lon)
        assertEquals("basis at $lat, $lon", basis, s.basis)
        assertEquals("zone at $lat, $lon (candidates ${s.candidates.map { it.label }})", ngs, s.suggested?.ngsZone)
        assertEquals(s.suggested, s.candidates.first())
    }

    @Test fun `resource loads with every zone except Alaska county-defined`() {
        val set = SpcsZoneSet.SPCS83
        val withBoundary = set.zones.filter { set.hasBoundary(it) }
        assertEquals(108, withBoundary.size)
        assertEquals(set.zones.filter { it.name.startsWith("Alaska") }.toSet(), (set.zones - withBoundary.toSet()).toSet())
    }

    /**
     * The committed resource is the generator's output; regenerate with gen_spcs_boundaries.py (the
     * output is byte-for-byte deterministic for the pinned inputs) and update this digest on purpose.
     */
    @Test fun `resource is the generated file`() {
        val bytes = File("src/main/resources/${SpcsZoneSet.SPCS83_BOUNDARY_RESOURCE}").readBytes()
        val hex = MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) }
        assertEquals("38b0006cd78efd8b4cd816e3cbdb97d1ecfef2684948accdc381075ddd22aa0f", hex)
    }

    @Test fun `Hazleton in Luzerne County is Pennsylvania North`() {
        // The smallest area-of-use box (Pennsylvania South) used to win here.
        val s = locator.locate(40.970000, -76.010000)
        assertEquals(SpcsZoneBasis.COUNTY_BOUNDARY, s.basis)
        assertEquals(6562, s.suggested!!.epsg)
        assertEquals(3701, s.suggested!!.ngsZone)
        assertFalse(s.isAmbiguous)
    }

    @Test fun `Pennsylvania South and Philadelphia`() {
        assertZone(3702, 40.2732, -76.8867)   // Harrisburg (Dauphin)
        assertZone(3702, 39.9526, -75.1652)   // Philadelphia, inside New Jersey's box but not NJ
        assertZone(3701, 41.3477, -76.0226)   // Wilkes-Barre
    }

    @Test fun `New York zones including Long Island`() {
        assertZone(3104, 40.7831, -73.9712)   // Manhattan
        assertZone(3104, 40.9124, -73.1234)   // Stony Brook, Suffolk
        assertZone(3101, 40.9312, -73.8988)   // Yonkers, Westchester
        assertZone(3102, 43.0481, -76.1474)   // Syracuse
        assertZone(3103, 42.8864, -78.8784)   // Buffalo
    }

    @Test fun `Texas zones`() {
        assertZone(4201, 35.2220, -101.8313)  // Amarillo
        assertZone(4202, 32.7767, -96.7970)   // Dallas
        assertZone(4203, 30.2672, -97.7431)   // Austin
        assertZone(4204, 29.7604, -95.3698)   // Houston
        assertZone(4205, 27.8006, -97.3964)   // Corpus Christi
    }

    @Test fun `California zones`() {
        assertZone(401, 40.5865, -122.3917)   // Redding
        assertZone(402, 38.5816, -121.4944)   // Sacramento
        assertZone(403, 37.7749, -122.4194)   // San Francisco
        assertZone(404, 36.7378, -119.7871)   // Fresno
        assertZone(405, 34.0522, -118.2437)   // Los Angeles
        assertZone(406, 32.7157, -117.1611)   // San Diego
    }

    @Test fun `independent cities and later counties`() {
        assertZone(4501, 38.8048, -77.0469)   // Alexandria VA (not in the EPSG list)
        assertZone(4501, 39.1857, -78.1633)   // Winchester VA (not in the EPSG list)
        assertZone(4502, 36.8508, -76.2859)   // Norfolk VA (listed)
        assertZone(2401, 38.6270, -90.1994)   // St. Louis city MO
        assertZone(501, 39.9205, -105.0867)   // Broomfield CO (created 2001)
    }

    @Test fun `Washington Grant County is split near 47 30 N`() {
        assertZone(4602, 47.3176, -119.5537)  // Ephrata
        assertZone(4601, 47.9415, -118.9978)  // Grand Coulee
    }

    @Test fun `Kentucky reports both legal zones`() {
        val s = locator.locate(38.0406, -84.5037)   // Lexington
        assertEquals(SpcsZoneBasis.COUNTY_BOUNDARY, s.basis)
        assertEquals(1601, s.suggested!!.ngsZone)
        assertEquals(listOf(1601, 1600), s.candidates.map { it.ngsZone })
        assertTrue(s.isAmbiguous)
    }

    @Test fun `Alaska falls back to area-of-use boxes`() {
        assertZone(5003, 64.8378, -147.7164, SpcsZoneBasis.AREA_OF_USE_BOX)   // Fairbanks
        assertZone(5004, 61.2181, -149.9003, SpcsZoneBasis.AREA_OF_USE_BOX)   // Anchorage
    }

    @Test fun `Puerto Rico`() {
        assertZone(5200, 18.4655, -66.1057)   // San Juan
    }

    @Test fun `ocean and abroad give no zone`() {
        for ((lat, lon) in listOf(51.5 to -0.1, 35.0 to -50.0, Double.NaN to 0.0)) {
            val s = locator.locate(lat, lon)
            assertEquals(SpcsZoneBasis.NONE, s.basis)
            assertNull(s.suggested)
            assertTrue(s.candidates.isEmpty())
        }
    }

    @Test fun `suggestFor delegates to the locator`() {
        assertEquals(3701, SpcsZone.suggestFor(40.97, -76.01)!!.ngsZone)
        assertEquals(3702, SpcsZone.suggestFor(39.9526, -75.1652)!!.ngsZone)
        assertNull(SpcsZone.suggestFor(51.5, -0.1))
    }
}
